        assertEquals("c-scan", ok.metadata().chunkId());
        assertEquals(9, ok.metadata().version());
        assertEquals("scan-src", ok.metadata().source());
        assertEquals(points.size(), ok.metadata().pointCount());
        assertEquals(blob.compression(), ok.metadata().compression());
        assertEquals(checksum, ok.metadata().checksum());
    }

    private static long headerSize(ChunkFileStore store, String fileName) throws IOException {
        Path file = store.getChunksDir().resolve(fileName);
        long size = Files.size(file);
        // NONE 回退时文件即 头+规范化字节；用差值返回头大小仅用于断言
        return 0;
    }

    private static ChunkMetadata metadata(String id, long version, String source,
                                          List<PointDatum> points,
                                          ChunkFileStore.StoredBlob blob, String checksum) {
        PointDatum first = points.get(0);
        PointDatum last = points.get(points.size() - 1);
        return new ChunkMetadata(id, version, source,
                Math.min(first.t(), last.t()), Math.max(first.t(), last.t()),
                new BBox(0, 0, 0, 1, 1, 1), points.size(), blob.compression(),
                checksum, blob.fileName(), blob.storedSize(), Instant.now());
    }

    /** AutoCloseable 占位以确保目录流关闭（测试辅助）。 */
    private static final class StreamQuiet implements AutoCloseable {
        @Override
        public void close() {
        }
    }
